import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { openDatabase, initSchema, toJob, HEARTBEAT_STALE_MS, type JobRow } from './db.ts';

const db = openDatabase();
initSchema(db);
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

const selectHeartbeat = db.prepare("SELECT at_ms FROM heartbeat WHERE name = 'worker'");
const selectAll = db.prepare('SELECT * FROM jobs ORDER BY seq DESC');
const selectById = db.prepare('SELECT * FROM jobs WHERE id = ?');
const selectByKey = db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?');
const insertJob = db.prepare(`
  INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress_completed,
                    created_at, updated_at, run_after, idempotency_key, idempotency_payload)
  VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, ?, 0, ?, ?)
  RETURNING *`);

interface FieldError {
  field: string;
  message: string;
}

interface NewJob {
  input: string;
  steps: number;
  failAttempts: number;
}

const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);
const KEY_PATTERN = /^[A-Za-z0-9_-]{1,128}$/;
const MAX_INPUT_LENGTH = 1000;

function send(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  const error: { code: string; message: string; fields?: FieldError[] } = { code, message };
  if (fields) error.fields = fields;
  send(res, status, { error });
}

function methodNotAllowed(res: ServerResponse): void {
  sendError(res, 405, 'method_not_allowed', 'Method not allowed');
}

function readBody(req: IncomingMessage): Promise<string> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    req.on('data', (chunk: Buffer) => chunks.push(chunk));
    req.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

function handleHealth(res: ServerResponse): void {
  const row = selectHeartbeat.get() as { at_ms: number } | undefined;
  const up = row !== undefined && Date.now() - Number(row.at_ms) <= HEARTBEAT_STALE_MS;
  send(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
}

function handleList(res: ServerResponse): void {
  const rows = selectAll.all() as unknown as JobRow[];
  send(res, 200, { jobs: rows.map(toJob) });
}

function handleGetOne(res: ServerResponse, rawId: string): void {
  let id: string;
  try {
    id = decodeURIComponent(rawId);
  } catch {
    sendError(res, 404, 'not_found', 'Job not found');
    return;
  }
  const row = selectById.get(id) as unknown as JobRow | undefined;
  if (!row) {
    sendError(res, 404, 'not_found', 'Job not found');
    return;
  }
  send(res, 200, toJob(row));
}

/** Validates a submission body. Returns the job to create, or every problem found. */
function validateCreate(contentType: string | undefined, idempotencyKey: string | string[] | undefined, raw: string): { job: NewJob; key: string | undefined } | { fields: FieldError[] } {
  const fields: FieldError[] = [];

  const mediaType = (contentType ?? '').split(';')[0]!.trim().toLowerCase();
  if (mediaType !== 'application/json') {
    fields.push({ field: 'body', message: 'Content-Type must be application/json' });
  }

  let key: string | undefined;
  if (idempotencyKey !== undefined) {
    if (typeof idempotencyKey === 'string' && KEY_PATTERN.test(idempotencyKey)) key = idempotencyKey;
    else fields.push({ field: 'Idempotency-Key', message: 'Idempotency-Key must match ^[A-Za-z0-9_-]{1,128}$' });
  }

  let parsed: unknown;
  let parsedOk = true;
  try {
    parsed = JSON.parse(raw);
  } catch {
    parsedOk = false;
  }

  const job: NewJob = { input: '', steps: 5, failAttempts: 0 };
  if (!parsedOk || typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
    fields.push({ field: 'body', message: 'Body must be a JSON object' });
  } else {
    const obj = parsed as Record<string, unknown>;
    for (const name of Object.keys(obj)) {
      if (!ALLOWED_FIELDS.has(name)) fields.push({ field: name, message: 'Unknown field' });
    }

    const input = obj.input;
    if (typeof input !== 'string' || input.length < 1 || input.length > MAX_INPUT_LENGTH || input.trim().length === 0) {
      fields.push({ field: 'input', message: `input must be a string of 1 to ${MAX_INPUT_LENGTH} characters that is not only whitespace` });
    } else {
      job.input = input;
    }

    const checkInt = (name: 'steps' | 'failAttempts', min: number, max: number, def: number): number => {
      const value = obj[name];
      if (value === undefined) return def;
      if (typeof value !== 'number' || !Number.isInteger(value) || value < min || value > max) {
        fields.push({ field: name, message: `${name} must be an integer from ${min} to ${max}` });
        return def;
      }
      return value;
    };
    job.steps = checkInt('steps', 1, 20, 5);
    job.failAttempts = checkInt('failAttempts', 0, 5, 0);
  }

  if (fields.length > 0) return { fields };
  return { job, key };
}

async function handleCreate(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const raw = await readBody(req);
  const checked = validateCreate(req.headers['content-type'], req.headers['idempotency-key'], raw);
  if ('fields' in checked) {
    sendError(res, 400, 'invalid_request', 'Invalid request', checked.fields);
    return;
  }

  const { job, key } = checked;
  // Canonical payload with defaults applied, in fixed key order, for idempotency comparison.
  const payload = JSON.stringify({ input: job.input, steps: job.steps, failAttempts: job.failAttempts });

  db.exec('BEGIN IMMEDIATE');
  let outcome: { status: number; row?: JobRow; conflict?: boolean };
  try {
    const existing = key === undefined ? undefined : (selectByKey.get(key) as unknown as JobRow | undefined);
    if (existing) {
      outcome = existing.idempotency_payload === payload ? { status: 200, row: existing } : { status: 409, conflict: true };
    } else {
      const now = new Date().toISOString();
      const row = insertJob.get(randomUUID(), job.input, job.steps, job.failAttempts, now, now, key ?? null, key === undefined ? null : payload) as unknown as JobRow;
      outcome = { status: 201, row };
    }
    db.exec('COMMIT');
  } catch (err) {
    db.exec('ROLLBACK');
    throw err;
  }

  if (outcome.conflict) {
    sendError(res, 409, 'idempotency_conflict', 'Idempotency-Key was already used with a different payload');
  } else {
    send(res, outcome.status, toJob(outcome.row!));
  }
}

async function route(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method ?? 'GET';

  if (pathname === '/') {
    if (method !== 'GET') return methodNotAllowed(res);
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }
  if (pathname === '/health') {
    if (method !== 'GET') return methodNotAllowed(res);
    return handleHealth(res);
  }
  if (pathname === '/api/jobs') {
    if (method === 'GET') return handleList(res);
    if (method === 'POST') return handleCreate(req, res);
    return methodNotAllowed(res);
  }
  const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (match) {
    if (method !== 'GET') return methodNotAllowed(res);
    return handleGetOne(res, match[1]!);
  }
  sendError(res, 404, 'not_found', 'Not found');
}

const server = createServer((req, res) => {
  route(req, res).catch((err: unknown) => {
    console.error('request failed:', err);
    if (res.headersSent) res.end();
    else sendError(res, 500, 'internal_error', 'Internal server error');
  });
});

let closing = false;
function shutdown(): void {
  if (closing) return;
  closing = true;
  // Fallback in case a connection refuses to close; unref so it never keeps the process alive.
  setTimeout(() => process.exit(0), 2000).unref();
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeAllConnections();
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

const port = Number(process.env.PORT ?? 3000);
server.on('error', (err) => {
  console.error('server error:', err);
  process.exit(1);
});
server.listen(port, () => console.log(`server listening on ${port}`));

