  WHERE status = 'running'`);
const claimNext = db.prepare(`
  UPDATE jobs SET status = 'running', attempts = attempts + 1, progress_completed = 0, updated_at = ?
  WHERE seq = (SELECT seq FROM jobs WHERE status = 'queued' AND run_after <= ? ORDER BY seq LIMIT 1)
  RETURNING *`);
const setProgress = db.prepare("UPDATE jobs SET progress_completed = ?, updated_at = ? WHERE id = ? AND status = 'running'");
const markCompleted = db.prepare(`
  UPDATE jobs SET status = 'completed', result_output = ?, progress_completed = steps, error = NULL, updated_at = ?
  WHERE id = ? AND status = 'running'`);
const markFailed = db.prepare(`
  UPDATE jobs SET status = 'failed', error = ?, result_output = NULL, updated_at = ?
  WHERE id = ? AND status = 'running'`);
const requeue = db.prepare(`
  UPDATE jobs SET status = 'queued', progress_completed = 0, run_after = ?, updated_at = ?
  WHERE id = ? AND status = 'running'`);

function beat(): void {
  try {
    upsertHeartbeat.run(Date.now());
  } catch (err) {
    console.error('heartbeat failed:', err);
  }
}

/** Processes one claimed attempt. `job.attempts` is this attempt's number. */
async function processJob(job: JobRow): Promise<void> {
  const attempt = job.attempts;

  if (attempt <= job.fail_attempts) {
    // Simulated transient failure at the first step, before any progress.
    await sleep(STEP_MS, undefined, { signal: controller.signal });
    const now = new Date().toISOString();
    if (attempt >= MAX_ATTEMPTS) {
      markFailed.run(TRANSIENT_ERROR, now, job.id);
    } else {
      requeue.run(Date.now() + RETRY_DELAY_MS, now, job.id);
    }
    return;
  }

  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS, undefined, { signal: controller.signal });
    setProgress.run(step, new Date().toISOString(), job.id);
  }
  markCompleted.run(job.input.toUpperCase(), new Date().toISOString(), job.id);
}

async function main(): Promise<void> {
  // A job left "running" by a previous worker is voided and re-run as the same attempt number.
  recoverRunning.run(new Date().toISOString());
  beat();
  const heartbeatTimer = setInterval(beat, HEARTBEAT_MS);

  console.log('worker started');
  while (!stopping) {
    let job: JobRow | undefined;
    try {
      const now = Date.now();
      job = claimNext.get(new Date(now).toISOString(), now) as unknown as JobRow | undefined;
    } catch (err) {
      console.error('claim failed:', err);
    }
    if (!job) {
      await pause(IDLE_MS);
      continue;
    }
    try {
      await processJob(job);
    } catch (err) {
      // Shutdown aborts the current step; anything else is logged and the loop carries on.
      if (!stopping) console.error(`job ${job.id} failed unexpectedly:`, err);
    }
  }

  clearInterval(heartbeatTimer);
  db.close();
  process.exit(0);
}

main().catch((err: unknown) => {
  console.error('worker crashed:', err);
  process.exit(1);
});

